<script setup lang="ts">
import * as echarts from 'echarts/core'
import { LineChart, PieChart } from 'echarts/charts'
import { GridComponent, LegendComponent, TooltipComponent } from 'echarts/components'
import { CanvasRenderer } from 'echarts/renderers'
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { RouterLink } from 'vue-router'
import client from '../api/client'
import WallPanel from '../components/WallPanel.vue'
import { fitWall } from '../components/wallFit'
import { ElMessage } from 'element-plus'
import { chartAppearance } from '../composables/chartAppearance'
import type { HistoryResponse } from '../api/monitorTypes'
import { loadSystemSettings, systemSettings } from '../stores/systemSettings'

echarts.use([LineChart, PieChart, GridComponent, LegendComponent, TooltipComponent, CanvasRenderer])

const root=ref<HTMLElement>(),trendEl=ref<HTMLElement>(),typeEl=ref<HTMLElement>(),data=ref<any>({states:{},latest_monitors:[],recent_incidents:[],probe_stats_24h:{}}),results=ref<any[]>([]),sla=ref<any[]>([]),now=ref(new Date()),updated=ref(''),connected=ref(false),error=ref(''),slaError=ref(false)
const motionPaused=ref(false),fullscreen=ref(false)
const stage=reactive({...fitWall(1920,1080),width:1920,height:1080})
const pages=reactive({business:0,nodes:0,events:0,stream:0,sla:0,inventory:0})
const pageItems=<T,>(items:T[]|undefined,page:number,size:number)=>(items||[]).slice(Math.min(page,Math.max(0,Math.ceil((items?.length||0)/size)-1))*size,(Math.min(page,Math.max(0,Math.ceil((items?.length||0)/size)-1))+1)*size)
let resizeFrame:number|undefined,lastRatio=0
const periodHours=ref(12),periodRange=ref<{after:string;before:string}|null>(null),trendLoading=ref(false)
const periodOptions=[{hours:1,label:'近 1 小时'},{hours:6,label:'近 6 小时'},{hours:12,label:'近 12 小时'},{hours:24,label:'近 24 小时'},{hours:72,label:'近 3 天'},{hours:168,label:'近 7 天'},{hours:720,label:'近 1 个月'}]
let refreshPending=false
let wallResize:ResizeObserver|undefined
const rangeTime=(value:string)=>new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})
function changePeriod(){requestVersion++;results.value=[];periodRange.value=null;load()}
let trend:any,typeChart:any,timer:number|undefined,clock:number|undefined,socket:WebSocket|undefined,reconnectTimer:number|undefined,reloadTimer:number|undefined,requestVersion=0,stopped=false
const stateText:Record<string,string>={UP:'正常',DOWN:'故障',DEGRADED:'降级',MAINTENANCE:'维护',PAUSED:'暂停',PENDING:'待探测',UNKNOWN:'未知'}
const monitorMap=computed(()=>Object.fromEntries((data.value.latest_monitors||[]).map((m:any)=>[m.id,m])))
const healthy=computed(()=>data.value.health_rate==null?'—':Number(data.value.health_rate).toFixed(1))
const recentSuccess=computed(()=>results.value.length?(results.value.filter(r=>r.success).length/results.value.length*100).toFixed(1):'—')
const slowest=computed(()=>[...results.value].filter(r=>r.latency_ms!=null).sort((a,b)=>b.latency_ms-a.latency_ms).slice(0,5))
const businessGroups=computed(()=>{
 const groups=new Map<string,{name:string;total:number;up:number;down:number;degraded:number}>()
 for(const monitor of data.value.latest_monitors||[]){const name=monitor.business||'未归属业务';const group=groups.get(name)||{name,total:0,up:0,down:0,degraded:0};group.total++;if(monitor.status==='UP')group.up++;if(monitor.status==='DOWN')group.down++;if(monitor.status==='DEGRADED')group.degraded++;groups.set(name,group)}
 return [...groups.values()].sort((a,b)=>(b.down+b.degraded)-(a.down+a.degraded)||a.name.localeCompare(b.name))
})
const riskCount=computed(()=>Number(data.value.states?.DOWN||0)+Number(data.value.states?.DEGRADED||0))
const posture=computed(()=>!updated.value?'等待监控快照':error.value?'数据同步异常':riskCount.value?'发现异常，需要关注':Number(data.value.open_incidents)>0?'存在待处理事件':(data.value.latest_monitors||[]).some((m:any)=>['PENDING','UNKNOWN'].includes(m.status))?'部分任务状态待确认':'业务运行平稳')
const periodPeak=computed(()=>{const valid=results.value.filter(r=>r.latency_ms!=null&&Number.isFinite(Number(r.latency_ms)));return valid.length?valid.reduce((max,r)=>Math.max(max,Number(r.latency_ms)),0):null})
const healthAngle=computed(()=>`${Math.max(0,Math.min(100,Number(data.value.health_rate)||0))*3.6}deg`)
const fmtTime=(v:any)=>v?new Date(v).toLocaleTimeString('zh-CN',{hour12:false}):'--:--:--'
const color=(status:string)=>({UP:'#43dfad',DOWN:'#ff758b',DEGRADED:'#ffbf69',MAINTENANCE:'#53beff',PENDING:'#91a6c0'}[status]||'#7d91ac')
function renderCharts(){
 if(!trendEl.value||!typeEl.value)return
 const ratio=Math.max(.5,Math.min(4,(window.devicePixelRatio||1)*stage.scale))
 if(Math.abs(ratio-lastRatio)>.05){trend?.dispose();typeChart?.dispose();trend=undefined;typeChart=undefined;lastRatio=ratio}
 trend??=echarts.init(trendEl.value,undefined,{devicePixelRatio:ratio});typeChart??=echarts.init(typeEl.value,undefined,{devicePixelRatio:ratio})
 const appearance=chartAppearance('dark'),grouped=new Map<string,any[]>()
 for(const r of [...results.value].reverse()){const points=grouped.get(r.monitor)||[];points.push([new Date(r.checked_at).getTime(),r.latency_ms]);grouped.set(r.monitor,points)}
 const legendHeight=32
 trend.setOption({...appearance,animation:false,grid:{left:44,right:18,top:legendHeight,bottom:30},legend:{type:'scroll',top:0,bottom:'auto',textStyle:appearance.textStyle},tooltip:{...appearance.tooltip,trigger:'axis',renderMode:'richText'},xAxis:{...appearance.xAxis,type:'time',min:periodRange.value?new Date(periodRange.value.after).getTime():undefined,max:periodRange.value?new Date(periodRange.value.before).getTime():undefined},yAxis:{...appearance.yAxis,type:'value',name:'ms'},series:[...grouped.entries()].map(([id,points])=>({name:monitorMap.value[id]?.name||id,type:'line',smooth:0.6,showSymbol:false,connectNulls:false,data:points,lineStyle:{width:2}}))},true)
 const counts:any={};for(const m of data.value.latest_monitors||[])counts[m.type]=(counts[m.type]||0)+1
 typeChart.setOption({animation:false,color:appearance.color,backgroundColor:appearance.backgroundColor,textStyle:appearance.textStyle,tooltip:{...appearance.tooltip,trigger:'item',renderMode:'richText'},legend:{type:'scroll',bottom:0,textStyle:{color:'#9fc2da',fontSize:10}},series:[{type:'pie',radius:['50%','72%'],center:['50%','43%'],label:{show:false},itemStyle:{borderColor:'#0b1d31',borderWidth:3,borderRadius:3},data:Object.entries(counts).map(([name,value],i)=>({name,value,itemStyle:{color:appearance.color[i%appearance.color.length]}}))}]},true)
 trend.resize();typeChart.resize()
}
async function load(){
 if(stopped)return
 if(trendLoading.value){refreshPending=true;return}
 trendLoading.value=true
 const version=++requestVersion,before=new Date(),after=new Date(before.getTime()-periodHours.value*3600000)
 try{
  const [summary,history,slaReport]=await Promise.all([
   client.get('/dashboard/summary/'),
   client.get<HistoryResponse>('/monitors/history/',{params:{checked_after:after.toISOString(),checked_before:before.toISOString(),page_size:1},timeout:60000}),
   client.get('/reports/sla/',{params:{days:1}}).then(response=>({...response,unavailable:false})).catch(()=>({data:{results:[]},unavailable:true}))
  ])
  if(stopped||version!==requestVersion)return
  data.value=summary.data
  results.value=history.data.series.map(point=>({id:point.id,monitor:point.monitor,checked_at:point.at,latency_ms:point.latency_ms,success:point.success})).reverse()
  periodRange.value={after:history.data.checked_after,before:history.data.checked_before}
  sla.value=slaReport.data.results||[];slaError.value=slaReport.unavailable
  updated.value=fmtTime(summary.data.snapshot_at||new Date());error.value=''
  await nextTick();renderCharts()
 }catch(e:any){if(!stopped&&version===requestVersion)error.value=e.response?.data?.message||'数据连接异常'}
 finally{trendLoading.value=false;if(refreshPending&&!stopped){refreshPending=false;load()}}
}

function scheduleLoad(){if(stopped||reloadTimer)return;reloadTimer=window.setTimeout(()=>{reloadTimer=undefined;load()},250)}
function connect(){const token=localStorage.getItem('access_token');if(!token||stopped)return;const scheme=location.protocol==='https:'?'wss':'ws';socket=new WebSocket(`${scheme}://${location.host}/ws/v1/status/?token=${encodeURIComponent(token)}`);socket.onopen=()=>{connected.value=true;if(reconnectTimer)clearTimeout(reconnectTimer)};socket.onclose=()=>{connected.value=false;if(!stopped)reconnectTimer=window.setTimeout(connect,3000)};socket.onerror=()=>socket?.close();socket.onmessage=(event)=>{try{const message=JSON.parse(event.data);if(message.type==='monitor.result')scheduleLoad()}catch{scheduleLoad()}}}
async function toggleFull(){try{document.fullscreenElement===root.value?await document.exitFullscreen():await root.value?.requestFullscreen()}catch{ElMessage.error('无法进入全屏，请允许浏览器全屏后重试')}}
function resize(){
 if(!root.value)return
 if(document.fullscreenElement!==root.value){const top=Math.max(0,root.value.getBoundingClientRect().top),wrapper=root.value.closest('.content-wrap'),bottom=wrapper?parseFloat(getComputedStyle(wrapper).paddingBottom)||0:16;root.value.style.setProperty('--wall-height',Math.max(260,innerHeight-top-bottom-2)+'px')}
 const width=root.value.clientWidth,height=root.value.clientHeight
 Object.assign(stage,fitWall(width,height),{width,height})
 if(resizeFrame)cancelAnimationFrame(resizeFrame)
 resizeFrame=requestAnimationFrame(()=>{resizeFrame=undefined;if(!stopped)renderCharts()})
}
function fullChanged(){fullscreen.value=document.fullscreenElement===root.value;nextTick(resize)}
onMounted(async()=>{stopped=false;if(typeof ResizeObserver!=='undefined'&&root.value){wallResize=new ResizeObserver(resize);wallResize.observe(root.value)}load();connect();try{await loadSystemSettings()}catch{systemSettings.monitor_wall_refresh_seconds=10}if(stopped)return;timer=window.setInterval(load,Math.max(5,Number(systemSettings.monitor_wall_refresh_seconds)||10)*1000);clock=window.setInterval(()=>now.value=new Date(),1000);window.addEventListener('resize',resize);window.visualViewport?.addEventListener('resize',resize);document.addEventListener('fullscreenchange',fullChanged);resize()})
onBeforeUnmount(()=>{stopped=true;requestVersion++;if(timer)clearInterval(timer);if(clock)clearInterval(clock);if(reconnectTimer)clearTimeout(reconnectTimer);if(reloadTimer)clearTimeout(reloadTimer);socket?.close();wallResize?.disconnect();trend?.dispose();typeChart?.dispose();window.removeEventListener('resize',resize);window.visualViewport?.removeEventListener('resize',resize);document.removeEventListener('fullscreenchange',fullChanged);if(resizeFrame)cancelAnimationFrame(resizeFrame)})

</script>
<template>
 <div ref="root" class="classic-wall" :class="{'motion-paused':motionPaused}" data-wall-theme="dark" :aria-busy="trendLoading&&!updated">
  <div class="classic-stage" :style="{width:stage.canvasWidth+'px',height:stage.canvasHeight+'px',transform:`scale(${stage.scale})`}">
   <header class="wall-header"><div><RouterLink to="/monitor-wall">‹ 大屏列表</RouterLink><span class="link-status">{{connected?'● 实时链路 ONLINE':'● 定时同步'}}</span></div><div class="title"><h1>{{systemSettings.monitor_wall_title}}</h1><small>HELI DATA · BUSINESS OBSERVABILITY COMMAND CENTER</small></div><div class="header-actions"><button :aria-pressed="motionPaused" @click="motionPaused=!motionPaused">{{motionPaused?'继续轮播 / 动效':'暂停轮播 / 动效'}}</button><button @click="toggleFull">{{fullscreen?'退出全屏':'⛶ 全屏'}}</button><div class="clock"><b>{{now.toLocaleTimeString('zh-CN',{hour12:false})}}</b><small>{{now.toLocaleDateString('zh-CN')}}</small></div></div></header>
   <section class="brief">
    <div class="posture" :class="{risk:riskCount>0||!!error}"><div class="health-orbit" :style="{'--health-angle':healthAngle}"><div><b>{{healthy}}<em v-if="healthy!=='—'">%</em></b><small>整体健康度</small></div></div><div><small>OPERATIONS COCKPIT / 运维驾驶舱</small><h2>{{posture}}</h2><p>{{data.states?.UP||0}} 项正常 · {{data.states?.DOWN||0}} 项故障 · {{data.states?.DEGRADED||0}} 项降级</p><span>{{error|| (updated?'当前快照 · '+updated:'正在连接监控数据')}}</span></div></div>
    <WallPanel v-model:page="pages.business" title="业务运行态势" :total="businessGroups.length" :page-size="2" :auto-rotate="!motionPaused" class="business-panel"><div v-if="!businessGroups.length" class="empty">暂无业务监控数据</div><div v-for="g in pageItems(businessGroups,pages.business,2)" :key="g.name" class="business-row"><b :title="g.name">{{g.name}}</b><span :class="{risk:g.down+g.degraded>0}">{{g.up}} / {{g.total}} 正常 · 故障 {{g.down}} · 降级 {{g.degraded}}</span><div class="track"><i :style="{width:g.up/g.total*100+'%'}"/></div></div></WallPanel>
    <div class="window-summary"><h2>选定周期观测 <small>{{periodOptions.find(o=>o.hours===periodHours)?.label}}</small></h2><div><span>原始探测记录<b>{{results.length.toLocaleString()}}</b></span><span>样本成功率<b>{{recentSuccess}}%</b></span><span>峰值响应<b>{{periodPeak==null?'—':periodPeak.toFixed(1)}}<em>ms</em></b></span></div><small>逐次原始数据 · 平滑曲线 · 不做均值聚合</small></div>
   </section>
   <section class="kpis"><div><span>业务系统</span><b>{{updated?data.businesses_total:'—'}}</b></div><div><span>监控任务</span><b>{{updated?data.monitors_total:'—'}}</b></div><div><span>整体健康度</span><b class="good">{{healthy}}<em v-if="healthy!=='—'">%</em></b></div><div><span>24H 探测</span><b>{{updated?data.probe_stats_24h?.total:'—'}}</b></div><div><span>24H 成功率</span><b class="good">{{data.probe_stats_24h?.success_rate??'—'}}<em>%</em></b></div><div><span>24H 失败</span><b :class="{risk:Number(data.probe_stats_24h?.failed)>0}">{{updated?data.probe_stats_24h?.failed:'—'}}</b></div><div><span>24H 平均响应</span><b>{{data.probe_stats_24h?.average_latency_ms==null?'—':Number(data.probe_stats_24h.average_latency_ms).toFixed(1)}}<em>ms</em></b></div><div><span>开放事件</span><b :class="{risk:Number(data.open_incidents)>0}">{{updated?data.open_incidents:'—'}}</b><small>今日 {{data.today_incidents||0}}</small></div></section>
   <main class="classic-grid">
    <WallPanel title="监控状态矩阵" hint="STATUS MATRIX" class="state-panel"><div v-for="(text,state) in stateText" :key="state" class="state-row"><i :style="{background:color(String(state))}"/><span>{{text}}</span><b>{{updated?data.states?.[state]||0:'—'}}</b></div></WallPanel>
    <WallPanel title="实时响应趋势" class="trend-panel"><div class="trend-toolbar"><small>{{trendLoading?'正在加载周期数据…':results.length+' 个原始点'}}<span v-if="periodRange"> · {{rangeTime(periodRange.after)}} — {{rangeTime(periodRange.before)}}</span></small><select v-model.number="periodHours" aria-label="响应趋势时间周期" @change="changePeriod"><option v-for="o in periodOptions" :key="o.hours" :value="o.hours">{{o.label}}</option></select></div><div ref="trendEl" class="trend-chart"/></WallPanel>
    <WallPanel v-model:page="pages.events" title="实时事件" :hint="'开放 '+(data.open_incidents??'—')+' · 最近 '+(data.recent_incidents?.length||0)+' 条'" :total="data.recent_incidents?.length||0" :page-size="2" :auto-rotate="!motionPaused" class="event-panel"><div v-if="!data.recent_incidents?.length" class="empty"><b>{{!updated?'等待监控快照':data.open_incidents?'存在待处理事件':'当前无开放事件'}}</b><small>以最近一次服务端快照为准</small></div><div v-for="i in pageItems<any>(data.recent_incidents,pages.events,2)" :key="i.id" class="incident"><span>{{i.severity}}</span><b :title="i.title">{{i.title}}</b><small>{{i.business}} · {{fmtTime(i.opened_at)}}</small></div></WallPanel>
    <WallPanel title="探测类型分布" hint="PROBE TYPES" class="type-panel"><div ref="typeEl" class="type-chart"/></WallPanel>
    <WallPanel v-model:page="pages.nodes" title="业务健康节点" :total="data.latest_monitors?.length||0" :page-size="6" :auto-rotate="!motionPaused" class="node-panel"><div class="nodes"><article v-for="m in pageItems<any>(data.latest_monitors,pages.nodes,6)" :key="m.id" :style="{'--status':color(m.status)}"><b :title="m.name">{{m.name}}</b><small>{{m.type}} · {{m.latency_ms==null?'—':m.latency_ms+' ms'}}</small><span>{{stateText[m.status]||m.status}}</span></article></div><div v-if="!data.latest_monitors?.length" class="empty">暂无监控任务</div></WallPanel>
    <WallPanel v-model:page="pages.stream" title="最近 9 次探测" hint="LATEST 9 PROBES" :total="Math.min(9,results.length)" :page-size="4" :auto-rotate="!motionPaused" class="stream-panel"><div v-for="r in pageItems(results.slice(0,9),pages.stream,4)" :key="r.id" class="stream-row"><i :style="{background:r.success?'#43dfad':'#ff758b'}"/><span :title="monitorMap[r.monitor]?.name">{{monitorMap[r.monitor]?.name||'探测任务'}}</span><em>{{r.latency_ms==null?'—':r.latency_ms+' ms'}}</em><small>{{fmtTime(r.checked_at)}}</small></div></WallPanel>
    <WallPanel v-model:page="pages.sla" title="24H SLA 可用率" :total="sla.length" :page-size="4" :auto-rotate="!motionPaused" class="sla-panel"><div v-if="slaError" class="empty">SLA 数据不可用或无报表查看权限</div><div v-else-if="!sla.length" class="empty">暂无 SLA 数据</div><div v-for="s in pageItems(sla,pages.sla,4)" :key="s.monitor_id" class="sla-row"><b :title="s.monitor_name+' · '+s.business_name+' · '+s.samples+' 个样本'">{{s.monitor_name}}</b><span :class="{warn:Number(s.availability)<99}">{{s.availability==null?'—':Number(s.availability).toFixed(3)+'%'}}</span><div class="track"><i :style="{width:(s.availability||0)+'%'}"/></div></div></WallPanel>
    <WallPanel v-model:page="pages.inventory" title="全量监控清单" :total="data.latest_monitors?.length||0" :page-size="5" :auto-rotate="!motionPaused" class="inventory-panel"><div v-for="m in pageItems<any>(data.latest_monitors,pages.inventory,5)" :key="m.id" class="inventory-row"><i :style="{background:color(m.status)}"/><b :title="m.name+' · '+m.business">{{m.name}}</b><small>{{m.type}}</small><span :style="{color:color(m.status)}">{{stateText[m.status]||m.status}}</span><em>{{m.latency_ms==null?'—':m.latency_ms+' ms'}}</em></div></WallPanel>
    <WallPanel title="性能热点 TOP 5" hint="周期内最慢单次探测" class="perf-panel"><div v-for="(r,index) in slowest" :key="r.id" class="perf-row"><b>0{{index+1}}</b><span :title="monitorMap[r.monitor]?.name">{{monitorMap[r.monitor]?.name||'探测任务'}}</span><em>{{Number(r.latency_ms).toFixed(2)}} ms</em><div class="track"><i :style="{width:(periodPeak?Number(r.latency_ms)/periodPeak*100:0)+'%'}"/></div></div><small class="sample-rate">周期样本成功率 {{recentSuccess}}%</small></WallPanel>
   </main>
   <footer><span :class="{risk:!!error}">{{error||'服务端快照 '+(updated||'—')}}</span><b>HELI MONITOR · 全域业务可用性监控</b><span>{{Math.round(stage.width)}} × {{Math.round(stage.height)}} · {{connected?'实时推送':'定时同步'}} · {{Math.max(5,Number(systemSettings.monitor_wall_refresh_seconds)||10)}}s</span></footer>
  </div>
 </div>
</template>
